// One entry per site. Add client sites here (keywords are what local customers search).
const SITES = {
  'dhobico.com': {
    base: 'https://dhobico.com',
    location: 'Hyderabad,Telangana,India',
    brand: ['dhobi & co', 'dhobi and co', 'dhobico'],
    keywords: [
      'ironing service in hyderabad',
      'steam ironing service hyderabad',
      'doorstep ironing service hyderabad',
      'ironing service near me',
      'laundry pickup and delivery hyderabad'
    ],
    maxPages: 20
  }
};
const site = String(($json.query || {}).site || '').toLowerCase().replace(/^www\./, '');
const cfg = SITES[site];
if (!cfg) throw new Error('Unknown site "' + site + '". Known: ' + Object.keys(SITES).join(', '));
return [{ json: { site, ...cfg } }];

// Deterministic checks done here, without paid APIs: sitemap URLs, homepage schema types, llms.txt, robots.txt.
const c = $('Config').first().json;
const get = async (url) => {
  try {
    const r = await this.helpers.httpRequest({ url, method: 'GET', returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 20000, headers: { 'User-Agent': 'LivoSEOBot/1.0' } });
    return { status: r.statusCode, body: typeof r.body === 'string' ? r.body : JSON.stringify(r.body) };
  } catch (e) { return { status: 0, body: '', error: e.message }; }
};
const locs = (xml) => [...xml.matchAll(/<loc>\s*([^<\s]+)\s*<\/loc>/g)].map(m => m[1]);

// Sitemap (handles a sitemap index one level deep)
const sm = await get(c.base + '/sitemap.xml');
let pages = [], sitemaps = [];
if (sm.status === 200) {
  if (/<sitemapindex/i.test(sm.body)) {
    sitemaps = locs(sm.body);
    for (const s of sitemaps.slice(0, 10)) { const r = await get(s); if (r.status === 200) pages.push(...locs(r.body)); }
  } else pages = locs(sm.body);
}
pages = [...new Set(pages)].filter(u => !/\.(jpg|jpeg|png|webp|gif|svg|pdf)$/i.test(u));
const home = c.base + '/';
const urls = [home, ...pages.filter(u => u.replace(/\/$/, '') !== c.base)].slice(0, c.maxPages);

// Homepage structured data (JSON-LD @type values)
const hp = await get(home);
const types = new Set();
for (const m of hp.body.matchAll(/<script[^>]*application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi)) {
  for (const t of m[1].matchAll(/"@type"\s*:\s*(\[[^\]]*\]|"[^"]+")/g)) {
    t[1].replace(/[\[\]"]/g, '').split(',').map(s => s.trim()).filter(Boolean).forEach(x => types.add(x));
  }
}
const llms = await get(c.base + '/llms.txt');
const robots = await get(c.base + '/robots.txt');

return [{ json: {
  urls,
  checks: {
    sitemap: { status: sm.status, isIndex: sitemaps.length > 0, childSitemaps: sitemaps.length, pagesListed: pages.length },
    homepage: { status: hp.status, jsonLdTypes: [...types], hasFaqText: /faq|frequently asked|got questions/i.test(hp.body) },
    llmsTxt: { status: llms.status, firstLine: llms.status === 200 ? llms.body.split('\n')[0].slice(0, 120) : null },
    robotsTxt: { status: robots.status, mentionsSitemap: /sitemap:/i.test(robots.body), disallowAll: /^disallow:\s*\/\s*$/im.test(robots.body) }
  }
} }];

// Compact summary for the agent: facts only, small enough for a cheap model.
const c = $('Config').first().json;
const d = $('Discover').first().json;
const dfsErr = (r) => (r && r.status_code && r.status_code !== 20000) ? r.status_message : null;
const errOf = (x) => (x && x.error) ? String(x.error.message || x.error.description || JSON.stringify(x.error)).slice(0, 400) : null;

// On-page (DataForSEO instant pages)
const op = $('OnPage').first().json || {};
// DataForSEO reports some checks as true when they are GOOD; everything else true is a problem.
const POSITIVE = new Set(['is_https','has_html_doctype','canonical','seo_friendly_url','is_www','has_micromarkup','has_meta_title','has_meta_description']);
const isPositive = (k) => POSITIVE.has(k) || k.startsWith('seo_friendly_url');
const pages = (op.tasks || []).map(t => {
  const it = (((t.result || [])[0] || {}).items || [])[0];
  if (!it) return { url: (t.data || {}).url, error: t.status_message };
  const m = it.meta || {};
  const issues = Object.entries(it.checks || {}).filter(([k, v]) => v === true && !isPositive(k)).map(([k]) => k);
  return {
    url: it.url, status: it.status_code, onpageScore: it.onpage_score,
    title: m.title || null, titleLength: m.title_length || (m.title || '').length,
    description: m.description || null, descriptionLength: m.description_length || (m.description || '').length,
    h1: ((m.htags || {}).h1 || []).slice(0, 3), canonical: m.canonical || null,
    internalLinks: m.internal_links_count, wordCount: (m.content || {}).plain_text_word_count,
    issues
  };
});

// PageSpeed (mobile, homepage)
const ps = $('PageSpeed').first().json || {};
const lh = ps.lighthouseResult || {};
const cat = lh.categories || {}, au = lh.audits || {};
const pagespeed = lh.categories ? {
  performance: Math.round((cat.performance || {}).score * 100),
  lcp: (au['largest-contentful-paint'] || {}).displayValue,
  cls: (au['cumulative-layout-shift'] || {}).displayValue,
  tbt: (au['total-blocking-time'] || {}).displayValue
} : { error: errOf(ps) || 'PageSpeed unavailable' };

// Rankings: organic + maps, one item per keyword (paired with the Keywords node)
const kws = $('Keywords').all().map(i => i.json.keyword);
const mine = (s) => { s = String(s || '').toLowerCase(); return s.includes(c.site) || c.brand.some(b => s.includes(b)); };
const organic = $('SERP').all().map((i, n) => {
  const r = ((i.json.tasks || [])[0]) || {};
  const items = ((((r.result || [])[0]) || {}).items || []).filter(x => x.type === 'organic');
  const hit = items.find(x => mine(x.domain) || mine(x.url));
  return { keyword: kws[n], position: hit ? hit.rank_group : null, url: hit ? hit.url : null,
           top3: items.slice(0, 3).map(x => x.domain), error: dfsErr(r) || errOf(i.json) || dfsErr(i.json) };
});
const maps = $('Maps').all().map((i, n) => {
  const r = ((i.json.tasks || [])[0]) || {};
  const items = ((((r.result || [])[0]) || {}).items || []);
  const hit = items.find(x => mine(x.domain) || mine(x.title));
  return { keyword: kws[n], position: hit ? hit.rank_group : null, matched: hit ? hit.title : null,
           top3: items.slice(0, 3).map(x => x.title + (x.rating ? ' (' + x.rating.value + '★/' + x.rating.votes_count + ')' : '')),
           error: dfsErr(r) || errOf(i.json) || dfsErr(i.json) };
});

const cost = [op, ...$('SERP').all().map(i => i.json), ...$('Maps').all().map(i => i.json)]
  .reduce((s, x) => s + (Number((x || {}).cost) || 0), 0);

return [{ json: {
  site: c.site, collectedAt: new Date().toISOString(),
  siteChecks: d.checks, pagesAudited: pages.length, onpageError: errOf(op) || dfsErr(op), pages, pagespeed,
  rankings: { location: c.location, organic, maps },
  dataforseoCostUsd: Math.round(cost * 10000) / 10000
} }];
